    for(int i=0;i<20&&!(host.Ready&&guest.Ready);i++){await host.Step(CancellationToken.None);await guest.Step(CancellationToken.None);}Check(host.Ready&&guest.Ready&&host.Sas==guest.Sas,"both devices show matching safety number");int before=hostGroup.Members.Count;host.Approve();for(int i=0;i<3;i++){await host.Step(CancellationToken.None);await guest.Step(CancellationToken.None);}Check(hostGroup.Members.Count==before&&guestGroup is null,"one-sided approval cannot add a device");guest.Approve();for(int i=0;i<20&&!(host.Done&&guest.Done);i++){await host.Step(CancellationToken.None);await guest.Step(CancellationToken.None);}Check(host.Done&&guest.Done&&guestGroup is not null,"two-sided approval installs signed group membership");return guestGroup!;}
