foreach(var source in new[]{(groupA,a,b),(groupA,a,c),(groupB,b,c)}){var remote=source.Item3.Member.Id==a.Member.Id?groupA:source.Item3.Member.Id==b.Member.Id?groupB:groupC;var forward=Groups.Channel(source.Item1,source.Item2,source.Item3.Member);var reverse=Groups.Channel(remote,source.Item3,source.Item2.Member);Check(forward.Key==reverse.Key&&forward.Device==reverse.Peer,"independent device pair derives matching authenticated channel");var envelope=Wire.Seal(forward,1,"mesh 中文");using var send=new RelayClient(forward);using var receive=new RelayClient(reverse);await send.Send(envelope,CancellationToken.None);var got=await receive.Receive("",CancellationToken.None);Check(got is not null&&Wire.Open(reverse,got).Text=="mesh 中文","group relay facade carries end-to-end ciphertext");}
var sendConfig=Groups.Channel(groupA,a,c.Member);var receiveConfig=Groups.Channel(groupC,c,a.Member);byte[] payload=RandomNumberGenerator.GetBytes(1024*1024+17);string sourceFile=Path.Combine(directory,"source.bin"),destination=Path.Combine(directory,"received.bin");File.WriteAllBytes(sourceFile,payload);var offer=new AttachmentOffer(Guid.NewGuid().ToString("N"),"source.bin","application/octet-stream","file",payload.Length,Groups.Hash(payload),(payload.Length+Attachments.ChunkSize-1)/Attachments.ChunkSize,DateTimeOffset.UtcNow.ToUnixTimeSeconds()+3600,"ready",a.Member.Id);using(var sender=new AttachmentClient(sendConfig))using(var receiver=new AttachmentClient(receiveConfig)){await sender.PutBundle(sourceFile,offer,CancellationToken.None);await receiver.GetBundle(offer,destination,CancellationToken.None);Check(File.ReadAllBytes(destination).SequenceEqual(payload),"group store transfers and decrypts bundle larger than JSON request limit");}
var tampered=Groups.Feed(groupB,b) with{Removed=[a.Member.Id]};Reject(()=>Groups.Accept(groupA,tampered),"server cannot forge group membership changes");Groups.Remove(groupA,a,b.Member.Id);Check(groupA.Removed.Contains(b.Member.Id),"signed removal marks device revoked");var d=GroupIdentity.Create(Guid.NewGuid().ToString("N"),"Untrusted D");Groups.Add(groupB,b,d.Member);Check(!Groups.Accept(groupA,Groups.Feed(groupB,b))&&!groupA.Members.ContainsKey(d.Member.Id),"revoked device cannot authorize new members on updated devices");
var revokeFeed=Groups.Feed(groupA,a);Groups.Accept(groupB,revokeFeed);var previousB=groupB;groupB=Groups.Install(previousB,await Pair(groupA,a,b),b);Check(!groupB.Removed.Contains(b.Member.Id)&&groupB.Members[b.Member.Id].Admission.Length==32,"fresh mutually approved pairing readmits the same device identity");Groups.Accept(groupB,revokeFeed);Check(!groupB.Removed.Contains(b.Member.Id),"old removal feed cannot revoke a new admission");Groups.Remove(groupA,a,b.Member.Id);Groups.Accept(groupB,Groups.Feed(groupA,a));Check(groupB.Removed.Contains(b.Member.Id),"new removal revokes the current admission");previousB=groupB;groupB=Groups.Install(previousB,await Pair(groupA,a,b),b);Check(!groupB.Removed.Contains(b.Member.Id)&&groupB.Sequence>previousB.Sequence,"repeated rejoin preserves author sequence and counters");Groups.Remove(groupA,a,a.Member.Id);Groups.Accept(groupB,Groups.Feed(groupA,a));var previousA=groupA;groupA=Groups.Install(previousA,await Pair(groupB,b,a),a);Groups.Validate(groupA);Check(!groupA.Removed.Contains(a.Member.Id),"group creator can leave and rejoin through another trusted member");
